// =============================================
// COURSE DETAILS PART 4 - Creativity & Design
// =============================================
(function() {
  const existing = typeof COURSE_DETAILS !== 'undefined' ? COURSE_DETAILS : {};
  existing['cre-graphic'] = [
    {
      intro: 'Graphic design is the art of visual communication. It combines images, typography, color, and layout to convey messages effectively. Whether you are designing a logo, a poster, a website, or a social media post, understanding design principles is the foundation of great visual work.',
      objectives: ['Understand the core principles of design', 'Use hierarchy, contrast, and alignment to guide the viewer', 'Apply color theory to create effective palettes', 'Use typography to enhance readability and mood'],
      sections: [
        { heading: '1. The Core Principles of Design', paragraphs: ['Design principles are the guidelines that help you arrange visual elements in a way that is both functional and aesthetically pleasing. The most important principles include: alignment, contrast, hierarchy, repetition, proximity, and balance.', 'Alignment creates order by lining up elements along common edges. Contrast draws attention by pairing different elements (dark/light, large/small). Hierarchy guides the eye from most to least important. Repetition creates consistency. Proximity groups related items. Balance distributes visual weight evenly.'], bullets: ['Alignment: lining up elements creates a clean, organized look', 'Contrast: differences in size, color, or weight create emphasis', 'Hierarchy: visual order of importance (headline, subhead, body)', 'Repetition: repeating styles creates consistency and brand identity', 'Proximity: grouping related elements reduces clutter', 'Balance: distributing visual weight symmetrically or asymmetrically'] },
        { heading: '2. White Space & Composition', paragraphs: ['White space (negative space) is the empty area around and between design elements. Far from being wasted, it is essential for readability and visual breathing room. It helps the eye navigate and makes the content feel premium and uncluttered.', 'Good composition uses white space intentionally. A common mistake is filling every pixel with content. Instead, give your elements room to breathe — the most important elements should have the most space around them to draw the eye.'], bullets: ['White space improves readability and focus', 'Empty space makes designs feel clean and premium', 'Use white space to separate and emphasize important elements', 'The 60-30-10 rule: 60% dominant, 30% secondary, 10% accent', 'Less is often more — remove unnecessary elements'] },
        { heading: '3. Applying the Principles', paragraphs: ['Professional designers apply these principles in every project. A well-designed poster uses hierarchy (big bold title, smaller subtitle, even smaller details), contrast (a bright accent color on a dark background), alignment (all text on a consistent grid), and balance (visual weight distributed across the layout).', 'To practice: take any existing design (poster, website, ad) and analyze it. What is the hierarchy? How is contrast used? Where is the white space? This analysis trains your eye to see design principles in action — and apply them in your own work.'], bullets: ['Analyze existing designs to see principles in action', 'Start with a clear hierarchy: what is the most important element?', 'Use contrast to make key elements stand out', 'Keep it simple: one clear message per design', 'Iterate: create multiple versions and refine the best one'], tip: 'When starting out, limit yourself to one accent color, two fonts, and plenty of white space. This constraint forces you to focus on layout and hierarchy.' }
      ],
      keyPoints: ['Alignment, contrast, hierarchy, repetition, proximity, and balance are the core design principles', 'White space is essential for readability and a premium feel', 'Hierarchy guides the viewer\'s eye from most to least important', 'Analyze professional designs to train your design eye'],
      summary: 'Graphic design is visual communication. By mastering the core principles — alignment, contrast, hierarchy, repetition, proximity, and balance — and using white space intentionally, you can create designs that are both beautiful and effective.'
    },
    {
      intro: 'Color is one of the most powerful tools in a designer\'s toolkit. It evokes emotion, communicates meaning, and creates brand recognition. Understanding color theory helps you choose palettes that work harmoniously and convey the right message.',
      objectives: ['Understand the psychology of color and its emotional impact', 'Use the color wheel to create harmonious palettes', 'Apply the 60-30-10 rule for balanced color use', 'Create accessible color combinations'],
      sections: [
        { heading: '1. Color Psychology', paragraphs: ['Colors evoke specific emotions and associations. Blue conveys trust, calm, and professionalism (used by banks and tech companies). Red conveys energy, passion, and urgency (used for sales and warnings). Green conveys growth, health, and nature. Yellow conveys optimism and warmth. Purple conveys luxury and creativity. Orange conveys enthusiasm and fun.', 'The context matters too — the same color can have different meanings in different cultures. Red means luck in China but danger in Western contexts. Consider your audience and the message you want to convey when choosing colors.'], bullets: ['Blue: trust, calm, professionalism', 'Red: energy, passion, urgency', 'Green: growth, health, nature, money', 'Yellow: optimism, warmth, attention', 'Purple: luxury, creativity, wisdom', 'Orange: enthusiasm, fun, affordability', 'Black: power, elegance, sophistication', 'White: purity, simplicity, cleanliness'] },
        { heading: '2. The Color Wheel & Harmonies', paragraphs: ['The color wheel shows the relationships between colors. Primary colors (red, yellow, blue) cannot be mixed from others. Secondary colors (orange, green, purple) are made by mixing primaries. Tertiary colors mix primary and secondary.', 'Color harmonies are pleasing combinations based on the wheel: Complementary (colors opposite each other — high contrast, energetic), Analogous (colors next to each other — harmonious, calm), Triadic (three evenly spaced colors — vibrant, balanced), and Monochromatic (shades of one color — clean, sophisticated).'], bullets: ['Complementary: opposite on the wheel (e.g., blue/orange) — high contrast', 'Analogous: adjacent on the wheel (e.g., blue/teal/green) — calm harmony', 'Triadic: three evenly spaced colors — vibrant and balanced', 'Monochromatic: one hue in different shades — clean and elegant', 'Split-complementary: one base color plus the two neighbors of its complement', 'Tetradic: four colors in two complementary pairs — rich but hard to balance'] },
        { heading: '3. Building Effective Palettes', paragraphs: ['A good palette uses the 60-30-10 rule: 60% dominant color (background), 30% secondary color (headings, supporting elements), and 10% accent color (buttons, highlights, calls to action). This creates a balanced, professional look.', 'For accessibility, ensure sufficient contrast between text and background. WCAG recommends a contrast ratio of at least 4.5:1 for normal text and 3:1 for large text. Tools like WebAIM\'s Contrast Checker help verify this.'], bullets: ['60-30-10 rule: dominant 60%, secondary 30%, accent 10%', 'Limit palettes to 2-4 main colors', 'Ensure text/background contrast of at least 4.5:1', 'Use color tools: Adobe Color, Coolors, Paletton', 'Test palettes in both light and dark themes'] }
      ],
      keyPoints: ['Colors evoke emotions: blue = trust, red = energy, green = growth', 'The color wheel helps create harmonies: complementary, analogous, triadic, monochromatic', 'Use the 60-30-10 rule for balanced color application', 'Ensure accessibility with sufficient text/background contrast'],
      summary: 'Color theory is both an art and a science. By understanding color psychology, using the color wheel to create harmonies, and applying the 60-30-10 rule, you can build palettes that are beautiful, meaningful, and effective.'
    },
    {
      intro: 'Typography is the art and technique of arranging type to make written language readable, legible, and appealing. The fonts you choose and how you use them dramatically affect how your message is perceived — from the mood it creates to how easily it is read.',
      objectives: ['Understand the anatomy of type and font categories', 'Choose font pairings that work well together', 'Use hierarchy to organize text', 'Apply typographic best practices for readability'],
      sections: [
        { heading: '1. Type Anatomy & Categories', paragraphs: ['Fonts are classified into categories. Serif fonts (like Times New Roman, Georgia) have small decorative strokes (serifs) at the ends of letters — they feel formal, traditional, and readable in print. Sans-serif fonts (like Arial, Helvetica, Inter) have clean lines without serifs — they feel modern, clean, and are preferred for screens.', 'Other categories: script fonts (handwritten, elegant — use sparingly), display fonts (decorative, for headlines only), and monospace (fixed-width, for code and technical content). Each has its place, and using the right type for the right job is essential.'], bullets: ['Serif: formal, traditional, readable in print (Georgia, Times)', 'Sans-serif: modern, clean, great for screens (Inter, Helvetica)', 'Script: handwritten, elegant — use sparingly for accents', 'Display: decorative, for headlines and branding', 'Monospace: fixed-width, for code (JetBrains Mono, Courier)'] },
        { heading: '2. Font Pairing', paragraphs: ['A good rule is to use 2-3 fonts maximum in a design: a display font for headlines, a body font for text, and optionally an accent font for special elements. Pairing a serif headline with a sans-serif body (or vice versa) creates contrast and visual interest.', 'Great pairings: Georgia + Inter, Playfair Display + Lato, Montserrat + Open Sans, Merriweather + Source Sans. When pairing, look for fonts that contrast (different styles) but complement each other (similar x-height or mood).'], bullets: ['Use 2-3 fonts maximum per design', 'Pair contrasting styles: serif headline + sans-serif body', 'Look for similar x-heights and moods', 'Never use more than one script or display font', 'Good pairings: Playfair Display + Lato, Montserrat + Open Sans, Merriweather + Source Sans'] },
        { heading: '3. Readability & Hierarchy', paragraphs: ['Typography hierarchy organizes text by importance: large bold headlines, medium subheadings, and smaller body text. This guides the reader\'s eye and makes content scannable. Use font size, weight, and color to create hierarchy.', 'Readability tips: body text at 16px or larger on screens, line-height of 1.5-1.7, line length of 45-75 characters, adequate letter-spacing for headings, and sufficient contrast. Justified text can create awkward gaps — left-aligned is usually better for web.'], bullets: ['Hierarchy: size, weight, and color signal importance', 'Body text: 16px+ on screens, line-height 1.5-1.7', 'Line length: 45-75 characters for comfortable reading', 'Headings: increase letter-spacing and weight', 'Left-align body text for web (avoid justification)'] }
      ],
      keyPoints: ['Serif fonts feel formal; sans-serif feel modern; display fonts are for headlines', 'Use 2-3 fonts maximum, pairing contrasting styles', 'Typography hierarchy (size, weight, color) guides the reader', 'Prioritize readability: size, line-height, line length, contrast'],
      summary: 'Typography is where form meets function. By understanding type categories, pairing fonts thoughtfully, and applying hierarchy and readability best practices, you can create text that is both beautiful and effortlessly readable.'
    }
  ];
  existing['cre-uxui'] = [
    {
      intro: 'UX (User Experience) and UI (User Interface) design are two sides of the same coin. UX is about how a product works and feels — the overall experience a user has. UI is about how it looks — the visual design of the interface. Both are essential for creating products users love.',
      objectives: ['Distinguish between UX and UI design', 'Understand the UX design process', 'Create wireframes and prototypes', 'Apply UI design principles to create polished interfaces'],
      sections: [
        { heading: '1. UX vs UI: The Difference', paragraphs: ['UX (User Experience) design is about the overall experience: how a user feels when using a product, how easily they can accomplish their goals, and how intuitive the flow is. It involves research, information architecture, wireframes, and usability testing.', 'UI (User Interface) design is about the visual layer: colors, typography, buttons, icons, spacing, and visual hierarchy. UI makes the product beautiful; UX makes it functional. A product needs both — beautiful UI with bad UX frustrates users, and great UX with ugly UI is hard to trust.'], bullets: ['UX: how it works — usability, flow, research, testing', 'UI: how it looks — colors, typography, layout, visual style', 'UX = the experience; UI = the interface', 'UX research informs UI design decisions', 'Both are essential for a successful product'] },
        { heading: '2. The UX Design Process', paragraphs: ['The UX process is user-centered: Research (understand users and their needs through interviews, surveys, and analytics), Define (articulate the problem and user needs through personas and problem statements), Ideate (brainstorm solutions), Prototype (create wireframes and interactive mockups), and Test (evaluate with real users and iterate).', 'Wireframes are low-fidelity layouts that focus on structure and functionality — not visual design. They map out where content, navigation, and interactive elements go. Prototypes add interactivity, allowing users to click through the flow.'], bullets: ['Research: user interviews, surveys, competitive analysis, analytics', 'Define: personas, user journeys, problem statements', 'Ideate: brainstorming, sketching, crazy 8s', 'Prototype: wireframes (low-fi) to interactive mockups (hi-fi)', 'Test: usability testing with real users, iterate based on findings'] },
        { heading: '3. UI Design Essentials', paragraphs: ['UI design applies visual principles to the interface: consistent spacing (use a 4px or 8px grid), clear visual hierarchy (size and color signal importance), effective color (accent for actions), readable typography, and intuitive iconography.', 'Design systems (like Material Design and Apple\'s HIG) provide reusable components, styles, and guidelines that ensure consistency across a product. Components — buttons, cards, inputs, modals — should be consistent in style and behavior throughout the product.'], bullets: ['Spacing: consistent 4px/8px grid system', 'Hierarchy: most important actions are most prominent', 'Color: use accent color for primary actions', 'Typography: readable, consistent type scale', 'Components: consistent buttons, inputs, cards, modals', 'Design systems: Material Design, Human Interface Guidelines'] }
      ],
      keyPoints: ['UX is how a product works; UI is how it looks', 'The UX process: research, define, ideate, prototype, test', 'Wireframes focus on structure; prototypes add interactivity', 'UI design applies consistent spacing, hierarchy, color, and typography'],
      summary: 'UX and UI design work together to create products that are both functional and delightful. By understanding the UX process and applying UI design principles, you can create interfaces that users find intuitive, beautiful, and enjoyable.'
    },
    {
      intro: 'User research is the foundation of great design. It reveals what users need, want, and struggle with — replacing assumptions with evidence. Research-driven design decisions are more likely to succeed because they are based on real user needs.',
      objectives: ['Choose the right research methods for different questions', 'Conduct user interviews and usability tests', 'Create personas and user journeys', 'Use research insights to inform design decisions'],
      sections: [
        { heading: '1. Research Methods', paragraphs: ['User research falls into two categories: qualitative (understanding the why — interviews, observations, usability tests) and quantitative (measuring the what — surveys, analytics, A/B tests). Both are valuable and answer different questions.', 'Interviews provide deep insights into user needs and motivations. Surveys gather data from a larger audience. Usability tests observe how users interact with a product to identify problems. Analytics reveal what users actually do at scale.'], bullets: ['Interviews: in-depth understanding of needs, motivations, pain points', 'Surveys: quantitative data from a larger sample', 'Usability testing: observe real users completing tasks', 'Analytics: behavioral data at scale (clicks, drop-offs)', 'A/B testing: compare two versions to see which performs better'] },
        { heading: '2. Personas & User Journeys', paragraphs: ['A persona is a fictional character that represents a user segment, based on research. It includes demographics, goals, frustrations, and behaviors. Creating personas helps the team empathize with users and design for real people, not generic "users."', 'A user journey maps the steps a user takes to accomplish a goal with your product — from awareness through engagement to completion. It highlights pain points, emotions, and opportunities for improvement at each step.'], bullets: ['Persona: name, photo, demographics, goals, frustrations, behaviors', 'Create 2-4 personas covering your main user segments', 'User journey: steps from awareness to completion', 'Map emotions and pain points at each step', 'Identify opportunities: where can the experience be improved?'] },
        { heading: '3. Testing & Iteration', paragraphs: ['Usability testing is the process of observing real users as they attempt to complete tasks with your product. It reveals whether your design is intuitive, where users get confused, and what needs improvement.', 'Test early and often. Even a quick test with 5 users can uncover 85% of usability issues. Test wireframes, prototypes, and live products. Observe what users do (not what they say) — their actions reveal the truth. Iterate based on findings and test again.'], bullets: ['Test with 5 users to uncover most usability issues', 'Test early: wireframes and prototypes, not just final products', 'Watch what users DO, not what they say', 'Take notes on: where they hesitate, get confused, or make errors', 'Iterate: fix issues, then test again to confirm improvements'] }
      ],
      keyPoints: ['Research replaces assumptions with evidence', 'Qualitative methods (interviews, tests) reveal the why; quantitative (surveys, analytics) measure the what', 'Personas and user journeys help teams design for real users', 'Test early and often — 5 users can uncover 85% of issues'],
      summary: 'User research is the compass that guides design. By choosing the right methods, creating personas and journeys, and testing with real users, you design products that genuinely meet user needs — not what you assume they need.'
    },
    {
      intro: 'Design systems are the backbone of scalable, consistent product design. They are collections of reusable components, guidelines, and standards that ensure every screen feels like part of the same product — no matter how many designers and developers are working on it.',
      objectives: ['Understand what a design system is and why it matters', 'Identify the key components of a design system', 'Use design tokens for consistency', 'Contribute to and maintain a design system'],
      sections: [
        { heading: '1. What is a Design System?', paragraphs: ['A design system is a comprehensive set of standards for design and development: design tokens (colors, typography, spacing), reusable UI components (buttons, inputs, cards, modals), patterns (how components work together), and guidelines (accessibility, voice, tone).', 'Design systems ensure consistency, speed up development (teams reuse instead of rebuild), improve quality (tested components), and enable collaboration (designers and developers share the same language). Famous examples: Material Design (Google), Carbon (IBM), and Polaris (Shopify).'], bullets: ['Design tokens: colors, typography, spacing, radii as named variables', 'Components: buttons, inputs, cards, modals, navigation — reusable', 'Patterns: how components combine to solve common problems', 'Guidelines: accessibility, best practices, voice and tone', 'Benefits: consistency, speed, quality, collaboration'] },
        { heading: '2. Design Tokens', paragraphs: ['Design tokens are the atomic values of a design system — named variables that store design decisions. Instead of using raw hex codes everywhere, you use tokens like $color-primary, $spacing-md, $font-body. This makes it easy to maintain consistency and update the system globally.', 'If you change $color-primary from blue to green, every component that uses that token updates automatically. Tokens also support theming — light/dark mode, brand variations — by swapping token values without changing component code.'], bullets: ['Tokens: $color-primary, $spacing-md, $font-size-lg', 'Centralize design decisions in named variables', 'Update once, reflect everywhere', 'Support theming: light/dark mode via token swapping', 'Platform-agnostic: CSS variables, SCSS, JSON, etc.'] },
        { heading: '3. Building & Maintaining a Design System', paragraphs: ['Building a design system starts with an audit: catalog existing components, identify inconsistencies, and define the shared vocabulary. Then create the core tokens and the most-used components first. Document everything — usage, do\'s and don\'ts, accessibility.', 'A design system is never finished — it evolves. Maintain it with: a governance model (who approves changes), versioning (semver for breaking changes), contribution guidelines, and regular reviews. The system should serve its users (the product teams), not the other way around.'], bullets: ['Audit: inventory existing components and inconsistencies', 'Start small: core tokens and high-use components first', 'Document: usage guidelines, do\'s and don\'ts, accessibility', 'Governance: clear process for proposing and approving changes', 'Version and release: semver for predictable updates'] }
      ],
      keyPoints: ['Design systems ensure consistency, speed, and quality at scale', 'Design tokens centralize design decisions as named variables', 'Components are reusable, tested building blocks', 'A design system needs governance, documentation, and versioning to thrive'],
      summary: 'Design systems enable teams to build consistent, high-quality products at scale. By establishing design tokens, reusable components, and clear guidelines — and maintaining them with governance — you create a foundation that accelerates every product team.'
    }
  ];
  existing['cre-write'] = [
    {
      intro: 'Every writer has a unique voice — a distinct combination of personality, perspective, and style that comes through in their writing. Finding your voice is not about copying others; it is about discovering and developing what makes your writing unmistakably yours.',
      objectives: ['Understand what writer\'s voice is and why it matters', 'Develop your voice through daily practice', 'Experiment with different styles and genres', 'Write freely without self-censorship'],
      sections: [
        { heading: '1. What is Voice?', paragraphs: ['Voice is the writer\'s personality on the page — the way you combine word choice, sentence rhythm, tone, and perspective. Two writers can write about the same topic and produce completely different pieces because their voices are different.', 'Voice is not something you invent; it is something you uncover. It develops naturally as you write more and become more comfortable expressing your unique perspective. The more authentic you are, the stronger your voice becomes.'], bullets: ['Voice = the writer\'s personality on the page', 'Word choice, rhythm, tone, and perspective shape voice', 'Voice is developed, not invented', 'Authenticity strengthens voice', 'Your unique experiences give you a unique voice'] },
        { heading: '2. Finding Your Voice Through Practice', paragraphs: ['The most reliable way to find your voice is to write regularly. Daily journaling, freewriting, and blogging all help you get comfortable with expressing your thoughts. Over time, patterns emerge — your themes, your word choices, your rhythm.', 'Read widely but write in your own way. Reading expands your toolkit and inspires you, but do not try to imitate other writers. Notice what you like about their style, but filter it through your own perspective. Experiment with different forms — essays, stories, poems, letters — to discover what feels most natural.'], bullets: ['Write daily: journal, freewrite, blog', 'Read widely: expand your toolkit and inspiration', 'Do not imitate: absorb, then filter through your own perspective', 'Experiment: try essays, stories, poems, letters', 'Be patient: voice develops over months and years'] },
        { heading: '3. Freewriting & First Drafts', paragraphs: ['Freewriting is writing continuously without stopping to edit or judge. Set a timer for 10-15 minutes and write whatever comes to mind. This silences the inner critic and lets your authentic voice emerge.', 'First drafts are supposed to be messy. Write first, edit later. Do not try to make it perfect in your head before it reaches the page. Get the raw material down, then shape it in revision. Anne Lamott famously calls them "shitty first drafts" — and that is exactly what they should be.'], bullets: ['Freewriting: continuous writing without editing or judging', 'Set a timer: 10-15 minutes of non-stop writing', 'Silence the inner critic: first drafts can be messy', 'Write first, edit later — do not perfect in your head', 'Raw material first, shape it in revision'] }
      ],
      keyPoints: ['Voice is the writer\'s personality on the page — developed, not invented', 'Daily practice and experimentation develop your unique voice', 'Freewriting silences the inner critic and lets your voice emerge', 'First drafts are supposed to be messy — edit in revision'],
      summary: 'Finding your voice is a journey, not a destination. By writing regularly, reading widely, experimenting with different forms, and giving yourself permission to write messy first drafts, your unique voice will emerge naturally and grow stronger with every word.'
    },
    {
      intro: 'Story structure is the framework that holds a story together. Whether you are writing a novel, a short story, a screenplay, or a personal essay, understanding narrative structure helps you create stories that are compelling, satisfying, and emotionally resonant.',
      objectives: ['Understand the classic story structure (exposition to resolution)', 'Apply the "show, don\'t tell" principle', 'Develop compelling characters', 'Use conflict and stakes to drive the narrative'],
      sections: [
        { heading: '1. The Classic Story Arc', paragraphs: ['The classic narrative arc has five stages: Exposition (introduce characters, setting, and situation), Rising Action (conflicts build, tension increases), Climax (the turning point — the most intense moment), Falling Action (consequences unfold), and Resolution (loose ends tied up, story concludes).', 'Not every story follows this exact shape — some are non-linear, some are episodic — but understanding the arc gives you a foundation. It helps you pace your story, build tension, and deliver a satisfying payoff.'], bullets: ['Exposition: introduce characters, setting, and the starting situation', 'Rising action: build conflict and tension', 'Climax: the turning point and peak of intensity', 'Falling action: consequences and aftermath', 'Resolution: conclusion, loose ends, emotional payoff'] },
        { heading: '2. Show, Don\'t Tell', paragraphs: ['"Show, don\'t tell" is the most famous writing advice. Instead of telling the reader that a character is angry ("He was angry"), show it through action and detail ("He slammed his fist on the table, his jaw tight, his voice a low growl").', 'Showing uses sensory details — what characters see, hear, feel, taste, and smell — to immerse the reader in the scene. It is more engaging because it lets the reader draw conclusions instead of being told. Use telling for transitions and summary; use showing for important moments.'], bullets: ['Telling: "She was nervous"', 'Showing: "Her hands trembled as she fumbled with the envelope"', 'Use sensory details: sight, sound, touch, taste, smell', 'Let readers draw conclusions through action and detail', 'Use telling for transitions; showing for important moments'] },
        { heading: '3. Character & Conflict', paragraphs: ['Stories are driven by characters who want something and face obstacles. A compelling protagonist has clear goals, strengths, flaws, and a character arc — they change over the course of the story. The antagonist (or opposing force) creates conflict.', 'Conflict comes in four types: person vs person, person vs self (internal struggle), person vs society, and person vs nature/fate. Stakes — what the character stands to gain or lose — make the conflict matter. Without meaningful stakes, the reader has no reason to care.'], bullets: ['Protagonist: wants something, has strengths and flaws, grows through the story', 'Antagonist: the opposing force creating conflict', 'Conflict types: person vs person, self, society, nature', 'Stakes: what the character stands to gain or lose', 'Character arc: how the character changes from beginning to end'] }
      ],
      keyPoints: ['The classic arc: exposition, rising action, climax, falling action, resolution', '"Show, don\'t tell" uses sensory details to immerse readers', 'Compelling characters have goals, flaws, and arcs', 'Conflict and meaningful stakes drive the narrative'],
      summary: 'Story structure is the skeleton of narrative. By mastering the classic arc, showing instead of telling, and building compelling characters with real conflict and stakes, you can craft stories that captivate readers from beginning to end.'
    },
    {
      intro: 'The saying "writing is rewriting" captures a fundamental truth: great writing is the result of revision. Your first draft is raw material — the real craft happens when you refine, restructure, and polish it. Editing transforms good ideas into great writing.',
      objectives: ['Understand the different levels of editing', 'Edit for structure, clarity, and style', 'Proofread effectively for errors', 'Develop a personal editing process'],
      sections: [
        { heading: '1. The Levels of Editing', paragraphs: ['Editing happens in layers. The first pass addresses structure: does the piece have a clear beginning, middle, and end? Are the sections in the right order? Is the argument or story logical and complete? This is where you move big chunks, cut entire sections, or add missing pieces.', 'Next comes line editing: word choice, sentence structure, rhythm, and clarity. Then copyediting: grammar, punctuation, spelling, and consistency. Finally, proofreading: catching typos and small errors before publication. Each layer builds on the previous one.'], bullets: ['Structural editing: order, logic, completeness, big changes', 'Line editing: word choice, sentence flow, clarity', 'Copyediting: grammar, punctuation, spelling, consistency', 'Proofreading: final typos and formatting check', 'Edit in layers — do not try to do everything at once'] },
        { heading: '2. Clarity & Concision', paragraphs: ['Clear writing is concise writing. Cut unnecessary words, eliminate jargon, and prefer strong verbs over adverbs. "She ran" is stronger than "She ran quickly." "He decided" beats "He came to a decision."', 'Read your sentences aloud. If a sentence feels awkward or confusing when spoken, revise it. Look for passive voice that obscures who did what ("The decision was made" — by whom?). Aim for sentences that are direct, active, and easy to follow.'], bullets: ['Cut unnecessary words and filler phrases', 'Prefer strong verbs over adverbs', 'Use active voice: "She wrote" vs "It was written"', 'Read aloud to catch awkward phrasing', 'One clear idea per paragraph'] },
        { heading: '3. Developing an Editing Process', paragraphs: ['Effective editing requires distance. Put your draft aside for a few hours or days before revising — you will see it with fresh eyes. Print it out or change the font to trick your brain into seeing it as new.', 'Read multiple times with different focuses: once for structure, once for clarity, once for errors. Read aloud to catch rhythm and flow issues. Ask someone else to read it — a second pair of eyes catches what you miss. Create a checklist of common mistakes you tend to make and check for them specifically.'], bullets: ['Get distance: set the draft aside before revising', 'Change fonts or print to see it fresh', 'Read with different focuses: structure, clarity, errors', 'Read aloud: catches rhythm and awkward phrasing', 'Get feedback: a second pair of eyes is invaluable', 'Keep a personal error checklist'] }
      ],
      keyPoints: ['Editing happens in layers: structure, line, copyedit, proofread', 'Clear writing is concise — cut words, use strong verbs, active voice', 'Get distance from your draft to see it with fresh eyes', 'Feedback and a personal error checklist improve your editing'],
      summary: 'Writing is rewriting. By editing in layers, prioritizing clarity and concision, developing a personal editing process, and welcoming feedback, you transform rough drafts into polished, powerful writing.'
    }
  ];
  existing['cre-video'] = [
    {
      intro: 'Great videos are made in pre-production. Planning your message, writing a script, and creating a storyboard before you pick up a camera saves time, money, and frustration — and results in a much better final product.',
      objectives: ['Define your message and target audience', 'Write a compelling video script', 'Create a storyboard to visualize scenes', 'Plan your equipment and logistics'],
      sections: [
        { heading: '1. Define Your Message & Audience', paragraphs: ['Before you shoot, know what you are making and why. What is the core message? Who is it for? What do you want the viewer to think, feel, or do after watching? A clear message keeps every decision — script, shots, music — aligned.', 'Understanding your audience shapes everything: the tone (formal or casual), the language (technical or plain), the pacing, and the platforms (YouTube, TikTok, Instagram). A video for teenagers on TikTok looks very different from one for executives on LinkedIn.'], bullets: ['Core message: what is the one thing viewers should remember?', 'Target audience: who are they, what do they care about?', 'Desired outcome: what should viewers think, feel, or do?', 'Platform: YouTube, TikTok, Instagram, LinkedIn — each has norms', 'A clear message guides every creative decision'] },
        { heading: '2. Writing the Script', paragraphs: ['The script is the blueprint of your video. Start with a strong hook in the first 5-10 seconds to capture attention. Structure the body around 3 key points. End with a clear call to action.', 'Write for the ear, not the eye. Spoken sentences are shorter and more conversational than written ones. Read your script aloud — if it feels awkward spoken, revise it. Aim for a natural, engaging delivery.'], bullets: ['Hook: capture attention in the first 5-10 seconds', 'Structure: 3 key points in the body', 'Call to action: what should viewers do next?', 'Write for the ear: short, conversational sentences', 'Read aloud: revise anything that sounds awkward'] },
        { heading: '3. Storyboarding & Planning', paragraphs: ['A storyboard is a sequence of drawings or images showing each shot in your video. It visualizes the composition, camera angles, and movement for every scene. Even simple stick-figure storyboards help you plan shots and avoid surprises on set.', 'Pre-production also includes: location scouting, lighting plans, equipment checklist (camera, lenses, tripod, microphone, lights), talent scheduling, and shot lists. The more you plan, the smoother your shoot day will be.'], bullets: ['Storyboard: visual plan of each shot (even stick figures work)', 'Shot list: camera angles, compositions, and movements', 'Location: scout and prepare the filming location', 'Equipment: camera, lens, tripod, mic, lights, batteries', 'Logistics: schedule talent, crew, and shoot day'] }
      ],
      keyPoints: ['Pre-production saves time and money — plan before you shoot', 'Define your message, audience, and desired outcome first', 'A script with a hook, 3 key points, and a call to action guides the video', 'Storyboards and shot lists prevent on-set surprises'],
      summary: 'Great videos start long before the camera rolls. By defining your message, writing a strong script, and planning your shots, you set yourself up for a smooth shoot and a video that truly resonates with your audience.'
    },
    {
      intro: 'Filming is where your plan becomes footage. Good lighting, clear audio, and stable shots are the three pillars of professional-looking video. You do not need expensive equipment to start — but you do need to master the fundamentals.',
      objectives: ['Light your scenes effectively', 'Capture clear audio', 'Shoot stable, well-composed shots', 'Use camera settings for the best quality'],
      sections: [
        { heading: '1. Lighting Basics', paragraphs: ['Good lighting is the single biggest factor in video quality. The three-point lighting setup is the standard: Key light (main light source, 45 degrees from camera), Fill light (opposite side, softer, reduces shadows), and Back light (behind the subject, separates them from the background).', 'Natural light is a great resource — shoot near windows during the day for soft, flattering light. The "golden hour" (sunrise and sunset) provides warm, beautiful light. Avoid shooting in harsh midday sun, which creates harsh shadows. If you cannot control the light, position your subject to face it.'], bullets: ['Three-point lighting: key, fill, back', 'Natural light: use windows and golden hour', 'Avoid harsh midday sun', 'Face your subject toward the light source', 'Diffuse light for softer shadows (curtains, diffusers)'] },
        { heading: '2. Audio Quality', paragraphs: ['Audio is arguably more important than video — viewers will tolerate imperfect visuals but not bad sound. Use an external microphone whenever possible. A lavalier (clip-on) mic is great for interviews. A shotgun mic on the camera works well for documentary-style shooting.', 'Record in a quiet environment: close windows, turn off fans and AC, and avoid echoey rooms. Monitor audio with headphones while recording. Leave 5 seconds of "room tone" (silence) at the start and end for editing flexibility.'], bullets: ['External mic: lavalier for interviews, shotgun for documentary', 'Quiet environment: close windows, turn off fans/AC', 'Monitor: use headphones while recording', 'Room tone: record 5 seconds of silence for editing', 'Camera mic is last resort — it picks up everything'] },
        { heading: '3. Composition & Stability', paragraphs: ['The rule of thirds divides the frame into a 3x3 grid. Place key elements (your subject\'s eyes, the horizon) along the lines or at the intersections for a balanced, professional composition. Leave headroom above the subject and look room in the direction they face.', 'Stable footage is essential. Use a tripod for static shots. For moving shots, use a gimbal, stabilizer, or steady hand. Move slowly and smoothly. If your footage is shaky, try to stabilize it in editing or reshoot — nothing looks more amateur than shaky video.'], bullets: ['Rule of thirds: place key elements on grid lines/intersections', 'Headroom: leave space above the subject\'s head', 'Look room: space in the direction the subject faces', 'Tripod: essential for stable static shots', 'Gimbal/stabilizer: for smooth moving shots', 'Set focus and exposure manually when possible'] }
      ],
      keyPoints: ['Lighting is the biggest factor in video quality — use three-point or natural light', 'Audio matters more than video — always use an external microphone', 'The rule of thirds creates balanced, professional compositions', 'Stable footage requires a tripod, gimbal, or steady technique'],
      summary: 'Filming well is about mastering the fundamentals: light your scenes, capture clean audio, compose with the rule of thirds, and keep your shots stable. Master these basics and your videos will look and sound professional — regardless of your equipment.'
    },
    {
      intro: 'Editing is where the video truly comes together. It is the art of selecting the best footage, arranging it into a compelling narrative, and polishing it with transitions, music, and color. Great editing can elevate mediocre footage — and poor editing can ruin great footage.',
      objectives: ['Understand the editing workflow and timeline', 'Cut footage for pacing and storytelling', 'Use transitions purposefully', 'Add music, sound effects, and color correction'],
      sections: [
        { heading: '1. The Editing Workflow', paragraphs: ['Editing starts with reviewing your footage and selecting the best takes (logging). Then assemble the rough cut — the basic sequence of scenes in order. Refine into the fine cut, tightening pacing and removing dead time. Add music, sound effects, and graphics. Finish with color correction and export.', 'Most editors use a non-linear editor (NLE) like Adobe Premiere Pro, Final Cut Pro, DaVinci Resolve, or CapCut. The timeline shows video on video tracks, audio on audio tracks. The playhead shows your current position. Master keyboard shortcuts to edit faster.'], bullets: ['Log: review and mark the best takes', 'Rough cut: basic assembly in order', 'Fine cut: tighten pacing, remove dead time', 'Add: music, SFX, graphics, color correction', 'NLEs: Premiere Pro, Final Cut Pro, DaVinci Resolve, CapCut'] },
        { heading: '2. Pacing & Storytelling', paragraphs: ['Editing is storytelling. Every cut should serve the narrative. Cut for rhythm and emotion: fast cuts for energy and excitement, longer takes for drama and tension. Remove anything that does not advance the story or add value.', 'A common beginner mistake is keeping every moment because you shot it. Be ruthless — if a shot does not serve the story, cut it. The "kill your darlings" principle applies: your favorite shot may be the one the video does not need. Tight pacing keeps viewers engaged.'], bullets: ['Every cut serves the story', 'Fast cuts = energy; long takes = drama', 'Remove anything that does not advance the narrative', 'Be ruthless: "kill your darlings"', 'Engagement drops if pacing lags'] },
        { heading: '3. Transitions, Music & Color', paragraphs: ['Transitions connect scenes — but less is more. Simple cuts are invisible and professional. Cross dissolves (fades) indicate time passing. Wipes and flashy effects are rarely appropriate. Use them sparingly and purposefully.', 'Music sets the emotional tone. Choose tracks that match the mood and edit to the beat for dynamic videos. Color correction fixes exposure and white balance; color grading creates a stylized look. Most NLEs have built-in color tools — start with basic corrections before creative grading.'], bullets: ['Simple cuts: invisible, professional default', 'Cross dissolve: passage of time', 'Music: sets emotion, edit to the beat', 'Color correction: fix exposure and white balance', 'Color grading: stylized look and mood', 'Export: match format to platform (1080p/4K, H.264)'] }
      ],
      keyPoints: ['Editing follows a workflow: log, rough cut, fine cut, add, finish', 'Every cut should serve the story — be ruthless with your footage', 'Use transitions sparingly; simple cuts are the professional default', 'Music and color correction enhance emotion and polish'],
      summary: 'Editing is where raw footage becomes a finished story. By mastering the workflow, cutting for pacing, and using transitions, music, and color purposefully, you can transform your footage into engaging, professional videos.'
    }
  ];
  existing['cre-photo'] = [
    {
      intro: 'Photography is the art of capturing light. Understanding your camera and the exposure triangle — aperture, shutter speed, and ISO — gives you creative control over every image you take.',
      objectives: ['Understand the exposure triangle: aperture, shutter speed, ISO', 'Control depth of field with aperture', 'Freeze or blur motion with shutter speed', 'Use ISO appropriately for different lighting'],
      sections: [
        { heading: '1. The Exposure Triangle', paragraphs: ['Exposure is the amount of light that reaches your camera\'s sensor. It is controlled by three settings: Aperture (the size of the lens opening), Shutter Speed (how long the sensor is exposed), and ISO (the sensor\'s light sensitivity). These three form the exposure triangle — change one, and you must adjust another to maintain correct exposure.', 'Each setting also has a creative effect: aperture controls depth of field, shutter speed controls motion blur, and ISO controls image noise. Understanding how they interact lets you make intentional creative decisions.'], bullets: ['Aperture: f-stop, size of lens opening — controls light AND depth of field', 'Shutter speed: exposure duration — controls light AND motion blur', 'ISO: sensor sensitivity — controls light AND noise', 'Correct exposure: the balance of all three', 'Stop: doubling or halving the amount of light'] },
        { heading: '2. Aperture & Depth of Field', paragraphs: ['Aperture is measured in f-stops: f/1.8, f/2.8, f/4, f/5.6, f/8, f/11, f/16, f/22. A lower f-number means a WIDER opening (more light) and a SHALLOWER depth of field (blurred background). A higher f-number means a NARROWER opening (less light) and a DEEPER depth of field (more in focus).', 'Use a wide aperture (f/1.8, f/2.8) for portraits to blur the background (bokeh) and isolate your subject. Use a narrow aperture (f/8, f/11) for landscapes to keep everything from foreground to background sharp. Remember: the f-number is a fraction — f/2 is a larger opening than f/8.'], bullets: ['Low f-number (f/1.8): wide opening, shallow depth of field, blurred background', 'High f-number (f/11): narrow opening, deep focus, sharp landscape', 'Portraits: wide aperture for bokeh and subject isolation', 'Landscapes: narrow aperture for front-to-back sharpness', 'F/8-f/11: the "sweet spot" for maximum sharpness on most lenses'] },
        { heading: '3. Shutter Speed & ISO', paragraphs: ['Shutter speed is measured in fractions of a second: 1/1000s, 1/250s, 1/60s, 1s. A fast shutter speed (1/500s+) freezes motion — great for sports and action. A slow shutter speed (1/30s or longer) blurs motion — great for silky waterfalls, light trails, and panning shots. Below 1/60s, use a tripod to avoid camera shake.', 'ISO controls the sensor\'s sensitivity to light. Low ISO (100, 200) gives clean, noise-free images — use in bright light. High ISO (1600, 3200+) makes the sensor more sensitive — use in low light, but expect increased noise (grain). Modern cameras handle high ISO well; the best ISO is always the lowest that gives correct exposure.'], bullets: ['Fast shutter (1/500s+): freezes motion', 'Slow shutter (1/30s-): blurs motion (tripod needed)', 'Low ISO (100-200): clean, noise-free images', 'High ISO (1600+): usable in low light, more noise', 'Rule of thumb: hand-hold down to 1/focal length (e.g., 1/50s for 50mm)'] }
      ],
      keyPoints: ['Exposure = aperture + shutter speed + ISO', 'Aperture controls depth of field; low f-stop = blurred background', 'Shutter speed controls motion; fast freezes, slow blurs', 'ISO trades light sensitivity for noise — use the lowest you can'],
      summary: 'Mastering the exposure triangle gives you complete creative control over your camera. By understanding how aperture, shutter speed, and ISO work together, you can achieve correct exposure and make deliberate creative choices in any situation.'
    },
    {
      intro: 'Composition is the art of arranging elements within the frame. Great composition draws the viewer\'s eye, creates visual interest, and communicates your subject effectively. You can take a technically perfect photo with bad composition — or a technically imperfect photo with brilliant composition.',
      objectives: ['Apply the rule of thirds for balanced composition', 'Use leading lines to guide the viewer\'s eye', 'Use framing and symmetry effectively', 'Understand the qualities of natural light'],
      sections: [
        { heading: '1. The Rule of Thirds', paragraphs: ['The rule of thirds divides your frame into a 3x3 grid of nine equal sections. Place key elements — your subject, the horizon, important lines — along the grid lines or at the intersections. This creates a more dynamic, balanced composition than centering everything.', 'The horizon should sit on the top third line (emphasizing the foreground) or bottom third line (emphasizing the sky) — never cutting the frame in half. Place a portrait subject\'s eyes on the top third line, with look room in the direction they face.'], bullets: ['Divide frame into 3x3 grid', 'Place key elements on lines or intersections', 'Horizon: top or bottom third, never the middle', 'Eyes: on the top third line in portraits', 'Look room: space in the direction the subject looks', 'Breaking the rule intentionally can create impact'] },
        { heading: '2. Leading Lines & Framing', paragraphs: ['Leading lines are lines within the composition that guide the viewer\'s eye toward your subject — roads, fences, rivers, railings, building edges, or shadows. They create depth and direct attention where you want it.', 'Framing uses elements in the foreground — archways, windows, tree branches, doorways — to surround your subject and draw the eye inward. Natural frames add depth and context, and they can make a scene feel more intimate.'], bullets: ['Leading lines: roads, fences, rivers, shadows that guide the eye', 'Leading lines add depth and direct attention', 'Framing: foreground elements (arches, windows, branches) surround the subject', 'Natural frames add depth and intimacy', 'Look for patterns, symmetry, and repetition'] },
        { heading: '3. Light & Timing', paragraphs: ['Light is the essence of photography. Golden hour (the hour after sunrise and before sunset) provides warm, soft, directional light that flatters subjects and landscapes. Blue hour (twilight) provides cool, moody tones. Overcast days provide soft, diffused light ideal for portraits and details.', 'Harsh midday sun creates unflattering shadows — avoid it when possible, or use shade. Side lighting emphasizes texture; backlighting creates silhouettes and rim light; front lighting is flat and even. Learn to see and use different qualities of light.'], bullets: ['Golden hour: warm, soft, directional — ideal for most photography', 'Blue hour: cool, moody, atmospheric', 'Overcast: soft, diffused — great for portraits', 'Avoid harsh midday sun or use shade', 'Side light: emphasizes texture', 'Backlight: silhouettes and rim light'] }
      ],
      keyPoints: ['The rule of thirds creates dynamic, balanced compositions', 'Leading lines guide the viewer\'s eye to the subject', 'Natural framing adds depth and intimacy', 'Light quality and timing dramatically affect your images'],
      summary: 'Composition and light are the soul of photography. By mastering the rule of thirds, using leading lines and framing, and understanding the qualities of natural light, you can transform ordinary scenes into compelling images.'
    },
    {
      intro: 'Post-processing is the digital darkroom. Modern photo editing is not about "fixing" bad photos — it is about enhancing good ones and expressing your creative vision. A subtle, thoughtful edit elevates an image; an overdone edit ruins it.',
      objectives: ['Understand the difference between correction and enhancement', 'Adjust exposure, contrast, and white balance', 'Use color adjustments purposefully', 'Develop a consistent editing workflow'],
      sections: [
        { heading: '1. Correction vs Enhancement', paragraphs: ['Color correction is the technical foundation: fixing exposure (too dark or bright), white balance (color casts), and contrast. These adjustments make the image look natural and accurate — like what you actually saw.', 'Enhancement is creative: boosting colors, adding drama, emphasizing certain tones, creating a mood. The best edits are invisible — viewers should feel the image is great, not notice the editing. "Less is more" is the golden rule.'], bullets: ['Correction: exposure, white balance, contrast — make it accurate', 'Enhancement: color grading, creative effects — make it expressive', 'The best edits are invisible', 'Less is more — subtlety wins', 'Edit to express your vision, not to compensate for mistakes'] },
        { heading: '2. Key Adjustments', paragraphs: ['Exposure controls overall brightness. Highlights and shadows adjust specific tonal ranges — recover blown-out highlights or lift shadow detail. Contrast separates dark and light tones for more punch. White balance removes color casts (too warm/cool) so whites look white.', 'Saturation and vibrance control color intensity. Saturation affects all colors equally; vibrance is smarter — it boosts muted colors without oversaturating skin tones. Use the histogram to check exposure: a well-exposed image has detail in both shadows and highlights.'], bullets: ['Exposure: overall brightness', 'Highlights/shadows: recover detail in specific ranges', 'Contrast: separation between dark and light', 'White balance: remove color casts for natural colors', 'Saturation vs vibrance: vibrance is smarter for skin tones', 'Histogram: check for clipped highlights/shadows'] },
        { heading: '3. Editing Workflow & Tools', paragraphs: ['A consistent workflow prevents over-editing. Start with global adjustments (exposure, contrast, white balance), then targeted adjustments (local corrections, dodging/burning), then creative grading. Step away and come back — fresh eyes catch over-edits.', 'Popular tools: Adobe Lightroom (catalog + editing), Photoshop (detailed retouching), Capture One, and free options like Darktable, RawTherapee, and Snapseed (mobile). Shoot RAW (not JPEG) for maximum editing flexibility — RAW files contain all the sensor data.'], bullets: ['Workflow: global → targeted → creative', 'Step away and return with fresh eyes', 'Lightroom: the industry standard for photo editing', 'Photoshop: detailed retouching and compositing', 'Shoot RAW for maximum editing flexibility', 'Export: save a high-res original and web-optimized copies'] }
      ],
      keyPoints: ['Correction makes images accurate; enhancement makes them expressive', 'Less is more — the best edits are invisible', 'Master exposure, contrast, white balance, and color adjustments', 'Shoot RAW and develop a consistent editing workflow'],
      summary: 'Post-processing is the final stage of creating a photograph. By mastering correction and enhancement, using a consistent workflow, and keeping your edits subtle, you can develop images that truly reflect your creative vision.'
    }
  ];
  existing['cre-music'] = [
    {
      intro: 'Music production is the process of creating music using digital tools. At the heart of modern music production is the Digital Audio Workstation (DAW) — software that lets you record, edit, arrange, and mix music. This lesson covers the fundamentals of setting up your production environment.',
      objectives: ['Understand what a DAW is and how it works', 'Set up your music production environment', 'Navigate the DAW interface: timeline, tracks, and mixer', 'Use virtual instruments and samples'],
      sections: [
        { heading: '1. What is a DAW?', paragraphs: ['A Digital Audio Workstation (DAW) is software used for recording, editing, mixing, and producing audio. Popular DAWs include Ableton Live (great for electronic music and live performance), FL Studio (popular for hip-hop and beats), Logic Pro (Mac, great all-rounder), Pro Tools (industry standard for recording studios), and GarageBand (free, great for beginners).', 'Each DAW has its own workflow, but they share core concepts: a timeline (arrangement view), tracks (audio and MIDI), a mixer (volume, pan, effects), and a library of instruments and effects.'], bullets: ['DAW: Digital Audio Workstation — software for music production', 'Ableton Live: electronic music, live performance', 'FL Studio: beats, hip-hop, pattern-based workflow', 'Logic Pro: Mac, all-rounder', 'Pro Tools: studio recording standard', 'GarageBand: free, ideal for beginners'] },
        { heading: '2. Understanding the Interface', paragraphs: ['The DAW interface has several key areas: the timeline (or arrangement view) where you place clips and patterns in time, the track lanes (audio and MIDI tracks), the mixer where you control volume, panning, and effects for each track, and the browser/library where you find instruments, samples, and effects.', 'Audio tracks contain recorded audio (from a microphone or instrument). MIDI tracks contain note data that triggers virtual instruments. The mixer lets you balance levels and add effects (EQ, compression, reverb) to individual tracks or the master output.'], bullets: ['Timeline: arrange clips and patterns over time', 'Tracks: audio tracks (recordings) and MIDI tracks (note data)', 'Mixer: volume, panning, and effects per track', 'Browser: instruments, samples, loops, effects', 'Transport controls: play, stop, record, loop', 'BPM (beats per minute): the tempo of your project'] },
        { heading: '3. Virtual Instruments & Sounds', paragraphs: ['Virtual instruments (VSTs, AUs) are software instruments that produce sound digitally. They include synthesizers (synths), samplers, drum machines, and realistic instrument emulations (pianos, strings, guitars). You play them via MIDI notes or program them in the piano roll.', 'In addition to instruments, producers use samples and loops — pre-recorded sounds (drums, vocals, effects) that can be triggered or placed in the timeline. Sound selection is a core skill: the right sounds make or break a track.'], bullets: ['Virtual instruments: synths, samplers, drum machines, instrument emulations', 'VST/AU: plugin formats for virtual instruments and effects', 'MIDI: note data that triggers virtual instruments', 'Piano roll: program MIDI notes visually', 'Samples/loops: pre-recorded sounds for drums, melodies, effects', 'Sound selection: choosing the right sounds is a core production skill'] }
      ],
      keyPoints: ['A DAW is the central tool for music production', 'Learn your DAW\'s interface: timeline, tracks, mixer, browser', 'Virtual instruments and samples are your sound sources', 'BPM sets the tempo; MIDI drives virtual instruments'],
      summary: 'Your DAW is your studio. By understanding its interface, setting up virtual instruments, and learning to work with MIDI, samples, and the mixer, you build the foundation for creating music of any genre.'
    },
    {
      intro: 'Rhythm is the heartbeat of music. Before melodies and harmonies, there is the beat — the pulse that makes people tap their feet. This lesson covers the rhythmic foundation of music production: tempo, drum patterns, and groove.',
      objectives: ['Understand tempo (BPM) and musical time', 'Build drum patterns with kick, snare, and hi-hat', 'Use quantization to fix timing', 'Create grooves that feel good'],
      sections: [
        { heading: '1. Tempo & Time Signatures', paragraphs: ['Tempo is the speed of the music, measured in Beats Per Minute (BPM). Slow tempos (60-90 BPM) feel relaxed; mid-tempos (90-120 BPM) are common in pop and hip-hop; fast tempos (120-180 BPM) drive electronic, dance, and rock music.', 'Time signatures define the meter. The most common is 4/4 — four beats per measure, with the quarter note getting one beat. Other signatures: 3/4 (waltz, three beats per measure), 6/8 (compound, six eighth notes), and 2/4 (marches). Most popular music is in 4/4.'], bullets: ['BPM: beats per minute — sets the tempo', 'Slow: 60-90 BPM (ballads, chill)', 'Mid: 90-120 BPM (pop, hip-hop)', 'Fast: 120-180 BPM (dance, rock)', '4/4 time: the most common time signature', 'The beat: typically on the quarter notes'] },
{ heading: '2. Drum Patterns', paragraphs: ['A basic drum pattern has three core elements: the Kick drum (on beats 1 and 3 in a standard four-on-the-floor pattern, or syncopated in hip-hop), the Snare (typically on beats 2 and 4 \u2014 the backbeat), and the Hi-hat (on every beat or eighth notes, open or closed for variation).', 'The kick provides the thump and defines the rhythm\'s foundation. The snare\'s backbeat on 2 and 4 is the most recognizable element in most music. The hi-hat provides the groove\'s pulse and texture. Build patterns by layering these elements in a drum machine or piano roll.'], bullets: ['Kick: low thump, foundation of the rhythm (beats 1, 3 or syncopated)', 'Snare: backbeat on 2 and 4 \u2014 the groove\'s anchor', 'Hi-hat: eighth-note pulse, open/closed for texture', 'Four-on-the-floor: kick on every beat (house, techno)', 'Half-time: snare on 3 (trap, hip-hop), creates a heavier feel'] },
        { heading: '3. Groove & Quantization', paragraphs: ['Groove is the rhythmic feel that makes music move. It comes from subtle timing variations — the slight push or pull of notes around the beat. Human drummers have natural groove; programmed drums can feel mechanical without it.', 'Quantization snaps notes to the nearest grid position, fixing timing errors. Full quantization makes things perfectly in time but can feel robotic. Producers often use "humanize" (slight random timing variations) or quantize to 50-80% to preserve groove. Swing (shuffle) delays every other eighth note for a laid-back feel.'], bullets: ['Groove: the feel created by subtle timing variations', 'Quantize: snap notes to the grid for perfect timing', '100% quantize: perfectly in time but can feel robotic', 'Humanize: add slight random variations for natural feel', 'Swing/shuffle: delay off-beats for a laid-back groove', 'Grid: the visual timing reference in your DAW'] }
      ],
      keyPoints: ['BPM sets the tempo; 4/4 is the most common time signature', 'Drum patterns layer kick, snare, and hi-hat', 'The backbeat (snare on 2 and 4) anchors the groove', 'Quantization fixes timing; humanize and swing create natural feel'],
      summary: 'Rhythm and beats are the foundation of music production. By understanding tempo, building drum patterns with kick, snare, and hi-hat, and mastering quantization and groove, you create the rhythmic backbone that makes music move.'
    },
    {
      intro: 'Melody and harmony are what make music memorable. The melody is the tune you hum; the harmony is the chords that support it. Understanding scales, chords, and how they work together unlocks your ability to write and produce compelling music.',
      objectives: ['Understand scales and their emotional qualities', 'Build chords from scales', 'Create melodies that work over chords', 'Use harmony to support and enhance the melody'],
      sections: [
        { heading: '1. Scales & Keys', paragraphs: ['A scale is a sequence of notes with a specific pattern of intervals. The major scale has a bright, happy sound. The natural minor scale has a darker, sad sound. Pentatonic scales (five notes) are used across blues, rock, and pop. These scales define the key of a piece.', 'The key tells you which notes are "in" the music. Most pop music uses the major or minor scale. Chords and melodies are built from the notes of the scale. Understanding scales helps you choose notes that fit together harmonically.'], bullets: ['Major scale: bright, happy, resolved', 'Minor scale: dark, sad, emotional', 'Pentatonic: five notes, used in blues/rock/pop', 'Key: the scale the music is based on', 'Chords and melodies are built from the scale', 'Intervals: the distances between notes that define scales'] },
        { heading: '2. Building Chords & Progressions', paragraphs: ['A chord is a group of notes played together, typically three or more. The most common chord is the triad — three notes built in thirds from a root: the root, third, and fifth. Major chords sound happy; minor chords sound sad. A chord built on the first degree of the major scale is the I chord (major); the second is ii (minor); the third is iii (minor); the fourth is IV (major); the fifth is V (major); the sixth is vi (minor); the seventh is vii° (diminished).', 'A chord progression is a sequence of chords. The most common progressions: I-V-vi-IV (used in countless pop songs — "Don\'t Stop Believin\'", "Let It Be"), vi-IV-I-V (another pop staple), and the 12-bar blues. Progressions create the harmonic foundation for melody.'], bullets: ['Triad: root, third, fifth — three notes', 'Major chords: happy; minor chords: sad', 'I-V-vi-IV: the most common pop progression', 'vi-IV-I-V: another pop staple', '12-bar blues: foundation of blues and rock', 'Diatonic chords: the chords built from the scale'] },
        { heading: '3. Writing Melodies & Harmony', paragraphs: ['A melody is a sequence of single notes that is memorable and singable. Good melodies have: a clear contour (rising and falling), repetition (motifs the listener can grasp), and a relationship to the harmony (notes that fit the chords beneath).', 'Harmony supports the melody. Each chord provides a set of notes that sound good together. Melody notes that are chord tones (part of the current chord) sound consonant and stable; non-chord tones add tension and color. Song structure — verse, chorus, bridge — organizes the melody and harmony into a coherent piece.'], bullets: ['Melody: memorable sequence of notes', 'Contour: rise and fall of the melody', 'Repetition: motifs and themes the listener remembers', 'Chord tones: consonant; non-chord tones: add tension', 'Verse-chorus-bridge: common song structure', 'Counter-melody: a secondary melody supporting the main one'] }
      ],
      keyPoints: ['Scales define the notes of a key; major is happy, minor is sad', 'Chords are built from scales; progressions create harmonic foundation', 'Common progressions: I-V-vi-IV and 12-bar blues', 'Melodies are memorable sequences that fit the harmony'],
      summary: 'Melody and harmony are the emotional core of music. By understanding scales, building chords and progressions, and crafting melodies that fit the harmony, you can write music that is memorable, expressive, and uniquely yours.'
    }
  ];
  existing['cre-animation'] = [
    {
      intro: 'Animation brings still images to life. The 12 principles of animation, developed by Disney animators Ollie Johnston and Frank Thomas, are the foundation of all animation — from classic cartoons to modern motion graphics and 3D films.',
      objectives: ['Understand the 12 principles of animation', 'Apply squash and stretch for elasticity', 'Use anticipation, staging, and timing effectively', 'Create believable motion and appeal'],
      sections: [
        { heading: '1. The 12 Principles Overview', paragraphs: ['The 12 principles are: Squash and Stretch, Anticipation, Staging, Straight Ahead and Pose to Pose, Follow Through and Overlapping Action, Slow In and Slow Out, Arcs, Secondary Action, Timing, Exaggeration, Solid Drawing, and Appeal.', 'These principles were developed to make animation more realistic, expressive, and engaging. While they were created for traditional hand-drawn animation, they apply equally to 2D digital animation, 3D (CGI), stop-motion, and motion graphics.'], bullets: ['Squash and Stretch: elasticity and weight', 'Anticipation: prepare the audience for an action', 'Staging: direct attention to the important action', 'Straight Ahead vs Pose to Pose: two animation approaches', 'Follow Through and Overlapping Action: secondary motion', 'Slow In and Slow Out: acceleration and deceleration', 'Arcs: natural curved motion paths', 'Secondary Action: supporting motions', 'Timing: number of frames, speed of action', 'Exaggeration: amplify actions for impact', 'Solid Drawing: volume, weight, and consistency', 'Appeal: charisma and visual interest'] },
        { heading: '2. Key Principles Explained', paragraphs: ['Squash and Stretch gives objects a sense of weight and elasticity — a bouncing ball stretches as it falls and squashes as it hits the ground. Anticipation prepares the audience: a character crouches before jumping, rears back before throwing. This makes actions read clearly.', 'Timing is the number of frames an action takes — it controls speed and emotion. Slow timing feels heavy and deliberate; fast timing feels energetic and snappy. Exaggeration amplifies actions beyond reality for comedic or dramatic effect — but it should stay grounded enough to remain believable.'], bullets: ['Squash and Stretch: exaggerated deformation suggests weight and flexibility', 'Anticipation: a small movement before the main action', 'Staging: clear silhouettes and composition focus attention', 'Timing: frames per action = speed and emotion', 'Exaggeration: push actions further for impact', 'Arcs: natural motion follows curved paths, not straight lines'] },
        { heading: '3. Applying the Principles', paragraphs: ['Start with simple exercises: animate a bouncing ball (squash and stretch, arcs, timing), a pendulum (follow through, slow in/out), and a character\'s head turn (anticipation, staging, appeal). These exercises build your animation instincts.', 'Study great animation frame by frame to see the principles in action. Analyze how Disney films, Pixar movies, and well-made motion graphics apply squash and stretch, anticipation, and timing. Understanding WHY something looks good is the key to doing it yourself.'], bullets: ['Start simple: bouncing ball, pendulum, head turn', 'Bouncing ball: squash and stretch + arcs + timing', 'Frame-by-frame study: analyze great animation', 'Reference: film real motion or use video reference', 'Iterate: block, refine, polish — like pose to pose'] }
      ],
      keyPoints: ['The 12 principles are the foundation of all animation', 'Squash and stretch, anticipation, and timing bring motion to life', 'Timing controls speed and emotion', 'Practice with simple exercises and study great animation'],
      summary: 'The 12 principles of animation transform static images into believable, expressive motion. By mastering squash and stretch, anticipation, timing, and the other principles, you can create animation that feels alive — whether in 2D, 3D, or motion graphics.'
    },
    {
      intro: 'Modern 2D animation is created with powerful digital tools. Whether you are making cartoons, explainer videos, or motion graphics, understanding keyframing, tweening, and your software\'s workflow is essential.',
      objectives: ['Understand the 2D animation software landscape', 'Use keyframes to define motion', 'Understand tweening and interpolation', 'Apply the animation workflow: block, refine, polish'],
      sections: [
        { heading: '1. 2D Animation Tools', paragraphs: ['Popular 2D animation tools: Adobe After Effects (industry standard for motion graphics), Toon Boom Harmony (professional frame-by-frame animation), Adobe Animate (vector animation for web and TV), Blender (free, with 2D Grease Pencil), and open-source options like OpenToonz and Synfig.', 'Each tool has strengths: After Effects excels at motion graphics and character rigging; Toon Boom is the choice for TV-quality frame-by-frame; Blender is free and powerful. Choose based on your goals and budget — many free options are excellent for learning.'], bullets: ['After Effects: motion graphics, rigging, compositing', 'Toon Boom Harmony: professional frame-by-frame TV animation', 'Adobe Animate: vector animation for web and TV', 'Blender: free, 2D Grease Pencil + full 3D', 'OpenToonz/Synfig: free open-source options', 'Choose based on your goals: motion graphics vs character animation'] },
        { heading: '2. Keyframes & Tweening', paragraphs: ['Keyframes define the start and end points of a motion or change. You set a keyframe for a property (position, scale, rotation) at one point in time, then another keyframe at a later time with a different value. The software interpolates the values between them — this is called tweening.', 'Tweening can be linear (constant speed) or eased (accelerating/decelerating). Easing (slow in/out) mimics natural motion and is essential for professional results. Most software lets you control easing curves for each keyframe.'], bullets: ['Keyframe: defines a value at a specific point in time', 'Tween: interpolation of values between keyframes', 'Linear tween: constant speed — mechanical', 'Eased tween: slow in/out — natural and smooth', 'Easing curves: fine control over acceleration', 'Spatial vs temporal: position paths and timing are separate'] },
        { heading: '3. The Animation Workflow', paragraphs: ['A professional animation workflow follows stages: Storyboard (plan the shots), Blocking (rough key poses to establish timing and composition), Refining (add breakdowns and in-betweens, smooth the motion), and Polish (add secondary action, fine-tune details).', 'In After Effects and similar tools, the workflow involves: setting up the composition, creating the elements, animating with keyframes, adding easing, layering effects, and rendering. Work in passes — get the timing right first, then refine the details.'], bullets: ['Storyboard: plan shots and action', 'Blocking: rough key poses for timing and composition', 'Refining: breakdowns, in-betweens, smooth motion', 'Polish: secondary action, detail, appeal', 'Composition: the canvas and time range for your animation', 'Render: export to video (H.264, ProRes) or GIF'] }
      ],
      keyPoints: ['Choose the right tool: After Effects (motion graphics), Toon Boom (frame-by-frame), Blender (free)', 'Keyframes define motion; tweening interpolates between them', 'Easing creates natural, professional motion', 'Follow the workflow: storyboard, block, refine, polish'],
      summary: 'Digital 2D animation is built on keyframes, tweening, and a solid workflow. By mastering these fundamentals and using the right tools, you can create smooth, expressive animation for cartoons, explainers, and motion graphics.'
    },
    {
      intro: 'Motion graphics combine graphic design and animation to communicate ideas dynamically. They are everywhere — explainer videos, title sequences, social media content, app interfaces, and advertising. This lesson covers the principles and process of creating effective motion graphics.',
      objectives: ['Understand what motion graphics are and where they are used', 'Combine text, shapes, and movement effectively', 'Follow the principles of good motion design', 'Create motion graphics for different media'],
      sections: [
        { heading: '1. What are Motion Graphics?', paragraphs: ['Motion graphics are animated graphic design elements — text, shapes, icons, and illustrations — used to communicate a message. Unlike character animation, which focuses on characters and storytelling, motion graphics focus on graphic elements and abstract motion.', 'They are used in: explainer videos (animated illustrations explaining concepts), title sequences (film and TV opening credits), social media content (animated posts and ads), user interface animations (transitions and micro-interactions), and data visualization (animated charts and infographics).'], bullets: ['Motion graphics: animated graphic design', 'Text, shapes, icons, and illustrations in motion', 'Explainer videos: communicate concepts visually', 'Title sequences: set the tone for film/TV', 'Social media: animated posts, ads, stories', 'Data visualization: animated charts and infographics'] },
        { heading: '2. Principles of Motion Design', paragraphs: ['Good motion design follows principles: Purpose (every movement should have a reason — to inform, emphasize, or delight), Simplicity (clear and focused, not busy), Timing (matching the pace to the message), Easing (natural acceleration/deceleration), and Hierarchy (animating important elements more prominently).', 'Motion should serve the message, not distract from it. If an animation does not clarify or enhance the message, cut it. Restraint is a virtue — professional motion graphics are often simpler than amateur ones, with deliberate, purposeful movement.'], bullets: ['Purpose: every motion should have a reason', 'Simplicity: clear and focused, not busy', 'Timing: pace matches the message', 'Easing: natural acceleration and deceleration', 'Hierarchy: emphasize what matters most', 'Restraint: less is often more'] },
        { heading: '3. Creating Motion Graphics', paragraphs: ['The process: Define the message (what do you want to communicate?), Storyboard (plan the sequence of scenes), Design the elements (text, shapes, illustrations in a consistent style), Animate (bring elements to life with keyframes, easing, and transitions), and Export (render for the target platform).', 'Build a cohesive style: consistent colors, typography, and illustration style across the piece. Use a storyboard to plan timing and transitions before animating. Match the motion to the brand or message — playful bouncy motion for fun brands, smooth professional motion for corporate.'], bullets: ['Define the message: what are you communicating?', 'Storyboard: plan scenes, timing, and transitions', 'Design: consistent style — colors, typography, illustrations', 'Animate: keyframes, easing, transitions, secondary motion', 'Export: match format and specs to the platform'] }
      ],
      keyPoints: ['Motion graphics animate graphic design elements to communicate messages', 'They are used in explainers, title sequences, social media, and data viz', 'Good motion is purposeful, simple, and well-timed', 'Follow the process: message, storyboard, design, animate, export'],
      summary: 'Motion graphics are a powerful communication tool. By combining design and animation with clear purpose and restraint, you can create dynamic content that explains, engages, and delights across any medium.'
    }
  ];
  existing['cre-arch'] = [
    {
      intro: 'Architecture is the art and science of designing spaces for human use. It balances form (how a building looks) with function (how it works). Understanding the fundamentals of spatial design opens the door to appreciating and creating meaningful built environments.',
      objectives: ['Understand the balance of form and function in architecture', 'Identify the key elements of architectural design', 'Understand proportion and scale', 'Consider the user experience of spaces'],
      sections: [
        { heading: '1. Form and Function', paragraphs: ['Form refers to the visual and physical shape of a building — its massing, silhouette, materials, and style. Function refers to how well it serves its purpose — how people move through it, how spaces are used, and how it performs environmentally.', 'The famous phrase "form follows function" (Louis Sullivan) suggests that a building\'s shape should be driven by its purpose. But great architecture goes beyond pure function — it also inspires, delights, and elevates the human experience.'], bullets: ['Form: massing, silhouette, materials, style', 'Function: usability, flow, performance, purpose', '"Form follows function" — purpose drives shape', 'Great architecture also inspires and delights', 'Balance: a building must work well AND look good'] },
        { heading: '2. Key Design Elements', paragraphs: ['Architectural design works with several key elements: Space (the void that people inhabit — the essence of architecture), Line (the edges and axes that define form and direction), Texture (surface qualities — rough, smooth, warm, cold), Light (natural and artificial — how it shapes mood and experience), and Color (which affects perception and emotion).', 'Architects manipulate these elements to create compositions that guide movement, frame views, and establish atmosphere. A corridor with strong directional lines leads the eye forward; a window strategically placed frames a view; warm materials create a sense of welcome.'], bullets: ['Space: the void people inhabit — the essence of architecture', 'Line: edges and axes that direct movement and define form', 'Texture: surface qualities that affect how spaces feel', 'Light: shapes mood, defines form, guides attention', 'Color: affects perception, mood, and identity'] },
        { heading: '3. Proportion, Scale & Experience', paragraphs: ['Proportion is the relationship between the sizes of different parts of a design. The golden ratio (approximately 1:1.618) has been used for millennia to create harmonious proportions in architecture. Good proportion makes a space feel balanced and pleasing.', 'Scale is the relationship between the size of a building and human size. Human scale makes people feel comfortable; monumental scale creates awe. The user experience of architecture — how it feels to move through, how it accommodates human needs — is as important as how it looks.'], bullets: ['Proportion: relationships between part sizes', 'Golden ratio (1:1.618): harmonious proportions', 'Scale: building size relative to humans', 'Human scale: comfortable, intimate', 'Monumental scale: awe-inspiring, institutional', 'User experience: how spaces feel and function for people'] }
      ],
      keyPoints: ['Architecture balances form (look) with function (purpose)', 'Key elements: space, line, texture, light, and color', 'Proportion and scale affect how spaces feel', 'User experience is central to good architecture'],
      summary: 'Architecture is about creating spaces that work well and feel right. By understanding the balance of form and function, the key design elements, and the importance of proportion and human experience, you can appreciate — and create — meaningful built environments.'
    },
    {
      intro: 'Interior design is the art of creating functional, beautiful interior spaces. It goes beyond decoration — it is about how a space works, how it feels, and how it reflects the people who live and work in it. This lesson covers the core principles of interior design.',
      objectives: ['Apply the principles of interior design: balance, rhythm, emphasis, scale, harmony', 'Create a cohesive color palette and mood', 'Layer lighting: ambient, task, and accent', 'Understand furniture arrangement and flow'],
      sections: [
        { heading: '1. Principles of Interior Design', paragraphs: ['The core principles: Balance (visual equilibrium — symmetrical, asymmetrical, or radial), Rhythm (visual movement through repetition, progression, or transition), Emphasis (a focal point that draws attention), Scale and Proportion (sizes relate appropriately to each other and the space), and Harmony (all elements work together cohesively).', 'A room should have a clear focal point — a fireplace, a piece of art, a dramatic view — and the other elements should support it. Rhythm guides the eye around the room through repeated colors, shapes, or materials.'], bullets: ['Balance: symmetrical (formal), asymmetrical (casual), radial', 'Rhythm: repetition, progression, transition create visual movement', 'Emphasis: one focal point per room', 'Scale/proportion: furniture fits the room and each other', 'Harmony: a cohesive relationship among all elements'] },
        { heading: '2. Color & Mood', paragraphs: ['Color is the most powerful mood-setting tool in interior design. Warm colors (reds, oranges, yellows) create energy and intimacy. Cool colors (blues, greens, purples) create calm and serenity. Neutrals (white, gray, beige) provide a grounding base.', 'A common approach: 60% dominant color (walls, large furniture), 30% secondary (rugs, curtains, accent furniture), 10% accent (art, pillows, decor). Use a consistent palette with a few key colors, and use the color wheel to find harmonious combinations.'], bullets: ['Warm colors: energy, intimacy (red, orange, yellow)', 'Cool colors: calm, serenity (blue, green, purple)', 'Neutrals: grounding base (white, gray, beige)', '60-30-10 rule: dominant, secondary, accent', 'Use the color wheel: analogous, complementary, monochromatic'] },
        { heading: '3. Lighting & Layout', paragraphs: ['Lighting is layered in three types: Ambient (general illumination — ceiling fixtures, natural light), Task (focused light for specific activities — desk lamps, reading lights, under-cabinet lights), and Accent (highlighting features — picture lights, spotlights on art or architectural details).', 'Furniture arrangement should support how the space is used. Create clear circulation paths, group furniture for conversation, and consider the flow of movement. The layout is the skeleton of the room — get it right, and the rest falls into place.'], bullets: ['Ambient: general illumination, the base layer', 'Task: focused light for activities (reading, cooking)', 'Accent: highlight art, architecture, focal points', 'Layout: support how the space is used', 'Circulation: clear paths for movement', 'Conversation zones: group seating for interaction'] }
      ],
      keyPoints: ['Interior design principles: balance, rhythm, emphasis, scale, harmony', 'Color palettes set the mood — use the 60-30-10 rule', 'Layer lighting: ambient, task, and accent', 'Layout and flow are the functional foundation of a room'],
      summary: 'Interior design combines aesthetics and function to create spaces that serve and inspire. By applying the core principles, choosing a cohesive palette, layering light, and planning the layout, you can transform any room into a beautiful, functional space.'
    },
    {
      intro: 'Sustainable design is about creating buildings and spaces that minimize environmental impact while maximizing human well-being. As climate change and resource scarcity become urgent challenges, sustainable design has moved from niche to essential.',
      objectives: ['Understand the environmental impact of buildings', 'Apply principles of sustainable and green building', 'Use natural materials and energy-efficient systems', 'Design for health, wellness, and resilience'],
      sections: [
        { heading: '1. Why Sustainable Design Matters', paragraphs: ['Buildings account for nearly 40% of global energy-related carbon emissions. They consume massive amounts of energy (heating, cooling, lighting), water, and raw materials. Sustainable design reduces this impact through energy efficiency, resource conservation, and healthier materials.', 'Sustainable design is not just about the environment — it also benefits occupants. Green buildings have better air quality, natural light, and thermal comfort, which improve health, productivity, and well-being. And energy-efficient buildings save money over time.'], bullets: ['Buildings: ~40% of global carbon emissions', 'Energy: heating, cooling, lighting consume huge amounts', 'Water and materials: significant resource consumption', 'Benefits: lower costs, healthier occupants, better productivity', 'It is essential, not optional — for the planet and people'] },
        { heading: '2. Principles of Green Building', paragraphs: ['Key principles: Energy efficiency (high-performance insulation, efficient HVAC, LED lighting, renewable energy like solar), Water conservation (low-flow fixtures, rainwater harvesting, greywater recycling), Sustainable materials (recycled, renewable, locally sourced, low-VOC), and Passive design (orientation, shading, natural ventilation, thermal mass).', 'Passive solar design uses the building\'s orientation and materials to capture heat in winter and reject it in summer — reducing the need for mechanical heating and cooling. This is one of the most effective and cost-efficient sustainable strategies.'], bullets: ['Energy: insulation, efficient HVAC, LED, solar panels', 'Water: low-flow fixtures, rainwater harvesting, greywater', 'Materials: recycled, renewable, local, low-VOC', 'Passive design: orientation, shading, natural ventilation', 'Thermal mass: materials that store heat (concrete, stone, brick)'] },
        { heading: '3. Health & Biophilic Design', paragraphs: ['Biophilic design connects building occupants with nature — a fundamental human need. It incorporates natural light, plants, natural materials, views of nature, and natural patterns. Research shows biophilic spaces reduce stress, improve mood, and boost creativity and productivity.', 'Designing for wellness also means: healthy indoor air quality (low-VOC materials, ventilation), thermal comfort (control over temperature), acoustic comfort (noise management), and access to nature and outdoor spaces. Sustainable design cares for people AND the planet.'], bullets: ['Biophilic: connect people with nature (plants, light, natural materials)', 'Reduces stress, improves mood, boosts productivity', 'Indoor air quality: low-VOC materials, good ventilation', 'Thermal and acoustic comfort: healthy, restful spaces', 'Access to nature: views, outdoor spaces, daylight'] }
      ],
      keyPoints: ['Buildings are a major source of emissions — sustainable design is essential', 'Green building: energy efficiency, water conservation, sustainable materials', 'Passive solar design reduces mechanical heating/cooling needs', 'Biophilic and wellness design improve health and productivity'],
      summary: 'Sustainable design addresses the urgent challenges of climate change and resource depletion while creating healthier, more beautiful spaces for people. By applying energy efficiency, passive design, sustainable materials, and biophilic principles, you design for the planet and for human flourishing.'
    }
  ];
  existing['cre-fashion'] = [
    {
      intro: 'Fashion is wearable art — a form of self-expression that communicates who we are without words. Understanding the fundamentals of fashion — silhouettes, fabrics, color, and personal style — helps you dress with confidence and intention.',
      objectives: ['Understand fashion as a form of self-expression', 'Build a capsule wardrobe of versatile staples', 'Understand the role of trends', 'Express your personal style with confidence'],
      sections: [
        { heading: '1. Fashion as Self-Expression', paragraphs: ['Fashion is one of the most visible forms of self-expression. What we wear communicates our personality, values, mood, and even our aspirations. It is a non-verbal language spoken by everyone, every day.', 'Developing personal style is not about following every trend — it is about discovering what makes you feel confident and authentic. Great style is a reflection of who you are, not a costume of what society expects.'], bullets: ['Fashion is non-verbal self-expression', 'Clothes communicate personality, values, and mood', 'Personal style: what makes YOU feel confident and authentic', 'Fashion is an art form and an industry', 'Style is personal — there is no single "right" way'] },
        { heading: '2. Building a Capsule Wardrobe', paragraphs: ['A capsule wardrobe is a curated collection of versatile, timeless pieces that can be mixed and matched to create many outfits. It focuses on quality over quantity and includes: neutral basics (white tee, black trousers, denim), a few statement pieces, and seasonally appropriate items.', 'The goal is a wardrobe where everything works together — fewer clothes, more outfit possibilities, less decision fatigue. Invest in well-made staples that fit well and flatter your body type; they will last for years and always look good.'], bullets: ['Capsule wardrobe: versatile, timeless, mix-and-match pieces', 'Basics: white tee, black trousers, denim, neutral knits', 'Quality over quantity: invest in well-made staples', 'Everything should coordinate — more outfits from fewer pieces', 'Less decision fatigue, more personal style'] },
        { heading: '3. Understanding Trends', paragraphs: ['Trends are constantly changing styles driven by fashion designers, cultural shifts, and the media. While trends can be fun to incorporate, they are not rules. Fast fashion pushes constant new trends at low prices — but often at great environmental and ethical cost.', 'A sustainable approach: build your wardrobe around timeless staples, then add a few on-trend pieces each season if you love them. Ask: does this trend fit my style and my life? If it does not, skip it. Your style should outlast any trend.'], bullets: ['Trends: constantly changing styles', 'Fast fashion: cheap, disposable, high environmental cost', 'Timeless staples: the foundation that outlasts trends', 'Add trends selectively: only if they fit your style', 'Ask: does this trend suit ME? If not, skip it'] }
      ],
      keyPoints: ['Fashion is wearable art and a form of self-expression', 'A capsule wardrobe of versatile staples simplifies and elevates your style', 'Trends come and go — timeless staples are the foundation', 'Personal style is about authenticity and confidence, not following rules'],
      summary: 'Fashion is a powerful tool for self-expression. By building a capsule wardrobe of quality staples, understanding trends without being controlled by them, and dressing for yourself, you can develop a personal style that is confident, sustainable, and uniquely yours.'
    },
    {
      intro: 'Fabric is the foundation of fashion. The material you choose determines how a garment looks, drapes, feels, and lasts. Understanding fibers and textiles is essential for making informed fashion choices — whether you are designing, buying, or styling.',
      objectives: ['Distinguish between natural and synthetic fibers', 'Understand the properties of common fabrics', 'Choose the right fabric for the garment\'s purpose', 'Care for fabrics properly'],
      sections: [
        { heading: '1. Natural Fibers', paragraphs: ['Natural fibers come from plants and animals. Cotton (from the cotton plant) is breathable, soft, and versatile — the most widely used fabric. Linen (from flax) is lightweight, breathable, and gets softer with washing — perfect for summer. Wool (from sheep) is warm, insulating, and naturally wrinkle-resistant. Silk (from silkworms) is luxurious, smooth, and drapes beautifully.', 'Each natural fiber has unique properties: cotton is comfortable and absorbent; linen is crisp and breathable; wool is warm and durable; silk is elegant and delicate. Natural fibers are generally more sustainable than synthetics but require proper care.'], bullets: ['Cotton: breathable, soft, versatile, absorbent', 'Linen: lightweight, breathable, crisp — ideal for warm weather', 'Wool: warm, insulating, durable, naturally wrinkle-resistant', 'Silk: luxurious, smooth, drapes beautifully, delicate', 'Natural fibers: generally more sustainable, need proper care'] },
        { heading: '2. Synthetic Fibers', paragraphs: ['Synthetic fibers are made from petroleum-based chemicals. Polyester is durable, wrinkle-resistant, and quick-drying — the most common synthetic, often blended with cotton. Nylon is strong and elastic — used for activewear and hosiery. Acrylic mimics wool but is lighter and less warm. Spandex (Lycra) is extremely stretchy — essential for activewear and fitted garments.', 'Synthetics are often cheaper and more durable than naturals, but they are derived from fossil fuels, do not biodegrade, and can be less breathable. Many garments blend natural and synthetic fibers to combine the best properties.'], bullets: ['Polyester: durable, wrinkle-resistant, quick-drying', 'Nylon: strong, elastic — activewear, hosiery', 'Acrylic: wool-like, lightweight', 'Spandex/Lycra: extremely stretchy — fitted garments', 'Blends: combine natural comfort with synthetic durability', 'Synthetics: petroleum-based, less breathable, not biodegradable'] },
        { heading: '3. Choosing & Caring for Fabrics', paragraphs: ['Choose fabric based on the garment\'s purpose: breathable cottons and linens for everyday and warm weather, warm wools for winter, stretchy blends for activewear, and silks or satins for formal occasions. Consider drape (how the fabric falls), weight, and care requirements.', 'Care tips: always check the care label, wash delicates (silk, wool) in cold water or by hand, air-dry where possible, and avoid high heat (which shrinks and damages fibers). Proper care extends the life of your clothes and reduces waste.'], bullets: ['Purpose first: breathable for summer, warm for winter, stretch for activewear', 'Drape: how fabric falls — silky drapes, stiff stands', 'Check care labels before washing', 'Delicates: hand wash or cold water', 'Air-dry: gentler on fabrics than machine drying'] }
      ],
      keyPoints: ['Natural fibers (cotton, linen, wool, silk) come from plants and animals', 'Synthetic fibers (polyester, nylon, spandex) are petroleum-based and durable', 'Choose fabric based on the garment\'s purpose and desired properties', 'Proper care extends the life of your clothes'],
      summary: 'Fabric is the soul of fashion. By understanding the properties of natural and synthetic fibers, choosing the right material for each garment, and caring for it properly, you make better fashion decisions — for your style, your budget, and the planet.'
    },
    {
      intro: 'Personal styling is the art of dressing in a way that reflects who you are and makes you look and feel your best. It is not about following trends or rules — it is about understanding your body, your lifestyle, and what makes you feel confident.',
      objectives: ['Dress for your body type and skin tone', 'Understand the importance of fit', 'Use accessories to elevate outfits', 'Develop a personal style that reflects your personality'],
      sections: [
        { heading: '1. Fit is King', paragraphs: ['Fit is the single most important factor in how you look. A well-fitted garment flatters your body regardless of its price or label; an ill-fitting garment ruins even the most expensive outfit. Shoulders should align with yours, sleeves end at the wrist, trousers break at the shoe, and nothing should pull or sag.', 'If a garment does not fit perfectly off the rack, consider a tailor. Alterations — taking in a waist, hemming trousers, shortening sleeves — are affordable and transform how clothes look on you. A $30 alteration can make a $100 garment look like $500.'], bullets: ['Fit is the most important factor in your look', 'Shoulders, sleeve length, trouser break, and waist matter', 'Nothing should pull, gap, or sag', 'Tailoring: affordable alterations transform fit', 'A good fit flatters regardless of brand or price'] },
        { heading: '2. Color & Body Type', paragraphs: ['Colors affect how you look and feel. Determine your skin\'s undertone — warm (yellow, golden), cool (pink, blue), or neutral — and choose colors that complement it. Warm undertones suit earthy tones (olive, rust, camel); cool undertones suit jewel tones (blue, emerald, purple).', 'Understanding your body type helps you choose silhouettes that flatter: balancing proportions, emphasizing your favorite features, and creating a visually pleasing line. The goal is not to hide your body — it is to dress it in a way that makes you feel confident.'], bullets: ['Warm undertones: earthy tones (olive, rust, camel)', 'Cool undertones: jewel tones (blue, emerald, purple)', 'Neutral undertones: most colors work', 'Body type: choose silhouettes that balance and flatter', 'Dress to feel confident, not to hide'] },
        { heading: '3. Accessories & Personal Style', paragraphs: ['Accessories elevate any outfit: a watch, belt, scarf, hat, bag, or jewelry. They add personality, color, and polish. The right accessory can transform a simple outfit into a memorable one. But restraint matters — one or two focal accessories are better than piling everything on.', 'Developing personal style: curate a wardrobe of pieces you love and feel good in. Create a style signature — a color you favor, a silhouette you repeat, an accessory you always wear. Style is a journey of self-discovery; it evolves as you do.'], bullets: ['Accessories: watch, belt, scarf, hat, bag, jewelry', 'Accessories add personality, color, and polish', 'Restraint: one or two focal pieces, not everything', 'Style signature: a repeated color, silhouette, or accessory', 'Style evolves — it is a journey of self-discovery'] }
      ],
      keyPoints: ['Fit is the most important factor in how you look', 'Choose colors that complement your skin undertone', 'Accessories elevate and personalize any outfit', 'Personal style reflects who you are — and evolves with you'],
      summary: 'Personal styling is about dressing for yourself. By prioritizing fit, choosing flattering colors and silhouettes, using accessories thoughtfully, and developing your own style signature, you can look and feel confident every day.'
    }
  ];
  existing['cre-game'] = [
    {
      intro: 'Game design is the art and science of creating interactive experiences. At its core is the game designer\'s craft: mechanics, dynamics, and aesthetics — the systems that make games fun, engaging, and meaningful.',
      objectives: ['Understand what makes a game a game', 'Learn the MDA framework: Mechanics, Dynamics, Aesthetics', 'Design engaging core mechanics', 'Understand the importance of meaningful player choices'],
      sections: [
        { heading: '1. What is a Game?', paragraphs: ['A game is an interactive experience with rules, goals, and feedback. Players make choices within a rule system to achieve goals, and the game provides feedback on their progress. Games are voluntary, structured play.', 'The essential elements: Rules (the constraints that define what players can and cannot do), Goals (what players are trying to achieve), Feedback (information about progress — scores, levels, visual/audio cues), and Interaction (the player\'s choices affect the outcome).'], bullets: ['Rules: the system of constraints and possibilities', 'Goals: objectives players strive to achieve', 'Feedback: information about progress (scores, levels)', 'Interaction: player choices that matter', 'Games are voluntary, structured play'] },
        { heading: '2. The MDA Framework', paragraphs: ['MDA is a framework for understanding game design: Mechanics (the rules and systems — the components of the game), Dynamics (the emergent behavior that arises when players interact with the mechanics), and Aesthetics (the emotional responses the game evokes — fun, challenge, discovery, expression).', 'Designers work from mechanics to aesthetics: they build systems that create dynamics that produce desired emotions. Players experience it in reverse: they feel the aesthetics, discover the dynamics, and eventually understand the mechanics.'], bullets: ['Mechanics: rules, systems, components', 'Dynamics: behavior arising from mechanics in play', 'Aesthetics: emotions the game evokes (fun, challenge, discovery)', 'Designer path: mechanics → dynamics → aesthetics', 'Player path: aesthetics → dynamics → mechanics'] },
        { heading: '3. Core Mechanics & Fun', paragraphs: ['Core mechanics are the repeatable actions players perform throughout the game — jumping, shooting, collecting, matching, trading. They are the verbs of the game. Good core mechanics are simple to understand but deep enough to master.', 'Fun comes from meaningful choices — decisions with real consequences. When players face interesting trade-offs (risk vs reward, short-term vs long-term), they are engaged. The best games create "interesting decisions" at every turn.'], bullets: ['Core mechanics: the repeatable verbs of the game', 'Simple to learn, deep to master', 'Meaningful choices: decisions with real consequences', 'Trade-offs: risk vs reward, short-term vs long-term', 'Interesting decisions are the source of fun'] }
      ],
      keyPoints: ['Games are interactive experiences with rules, goals, feedback, and choices', 'The MDA framework: Mechanics, Dynamics, Aesthetics', 'Core mechanics are the repeatable verbs of the game', 'Fun comes from meaningful choices and interesting trade-offs'],
      summary: 'Game design is the craft of creating meaningful choices within rule systems. By understanding the elements of games, applying the MDA framework, and designing core mechanics that produce interesting decisions, you can create experiences that are genuinely fun.'
    },
    {
      intro: 'Game engines are the tools that bring game designs to life. Modern engines handle rendering, physics, audio, input, and much more — letting developers focus on gameplay rather than low-level technical details. Choosing the right engine and workflow is critical.',
      objectives: ['Understand the major game engines and their languages', 'Choose the right engine for your project', 'Prototype gameplay with simple shapes', 'Use version control and collaboration tools'],
      sections: [
        { heading: '1. Major Game Engines', paragraphs: ['Unity is the most popular engine — used by indie and AAA studios alike. It uses C# and excels at 2D, mobile, and VR games. Unreal Engine uses C++ and Blueprints (visual scripting) and is known for stunning 3D graphics — used for AAA games like Fortnite. Godot is a free, open-source engine that is lightweight and beginner-friendly, supporting GDScript (Python-like).', 'Other options: GameMaker (2D-focused, beginner-friendly), Construct (no-code 2D), and custom engines (for learning or specialized needs). For beginners, Godot or Unity are excellent starting points.'], bullets: ['Unity: C#, most popular, great for 2D/mobile/VR', 'Unreal: C++ and Blueprints, AAA 3D graphics', 'Godot: free, open-source, lightweight, beginner-friendly', 'GameMaker: 2D-focused, visual and GML scripting', 'Construct: no-code 2D game creation'] },
        { heading: '2. Prototyping First', paragraphs: ['The most important advice in game development: prototype first. Build your core gameplay with simple shapes (cubes, circles, placeholders) before investing in art, sound, or polish. This lets you test whether the game is FUN before spending weeks on visuals.', 'A gameplay prototype answers: is the core mechanic fun? Does the game loop work? Is the difficulty right? If the prototype is not fun, no amount of beautiful art will fix it. Polish comes after the fun is proven.'], bullets: ['Prototype: build core gameplay with simple shapes', 'Test the fun BEFORE investing in art and polish', 'Does the core mechanic feel good?', 'Is the game loop engaging?', 'Polish comes after the fun is proven'] },
        { heading: '3. Collaboration & Workflow', paragraphs: ['Version control is essential for any team — it tracks changes, enables collaboration, and lets you revert mistakes. Git with GitHub/GitLab is the standard. Game-specific tools like Plastic SCM handle large binary assets well.', 'A typical workflow: plan the milestone, break work into tasks, use a project board (Jira, Trello, GitHub Projects), branch for features, test, and merge. Communicate regularly — games are complex, and teams succeed on alignment and communication.'], bullets: ['Version control: Git + GitHub/GitLab or Plastic SCM', 'Large binary assets: game-specific version control', 'Project boards: Jira, Trello, GitHub Projects', 'Break work into small, testable tasks', 'Communicate regularly — alignment is key'] }
      ],
      keyPoints: ['Unity (C#), Unreal (C++), and Godot are the major game engines', 'Prototype core gameplay with simple shapes before investing in art', 'Version control (Git) is essential for teams', 'A clear workflow and communication keep game projects on track'],
      summary: 'Game engines are your development platform. By choosing the right engine, prototyping the fun first, and using proper collaboration tools, you can bring your game ideas to life efficiently and effectively.'
    },
    {
      intro: 'Level design is the art of creating spaces that guide players through challenges, teach mechanics, and deliver memorable moments. A great level teaches without words, challenges without frustration, and rewards without hand-holding.',
      objectives: ['Understand the goals of level design', 'Introduce mechanics gradually', 'Design challenges with appropriate pacing', 'Use player testing to improve levels'],
      sections: [
        { heading: '1. Guiding the Player', paragraphs: ['A level is a teacher and a guide. It should communicate where to go and what to do through environmental cues — lighting, color, landmarks, and composition — without explicit instructions. The level design itself should teach the player.', 'Visual guidance techniques: bright lights and focal points draw the eye, paths and lines lead forward, distinctive landmarks orient the player, and consistent visual language (red = danger, green = safe) communicates meaning instantly.'], bullets: ['Lighting: bright focal points draw the eye', 'Paths and lines: lead the player forward', 'Landmarks: help players orient themselves', 'Visual language: consistent color coding (red = danger)', 'Show, don\'t tell: the level teaches without words'] },
        { heading: '2. Teaching Mechanics Gradually', paragraphs: ['Introduce mechanics one at a time. The classic pattern: present the mechanic in a safe environment (teach), then combine it with existing mechanics (reinforce), then test it under pressure (challenge). Each new mechanic should be introduced, practiced, and mastered before the next appears.', 'The "Safe → Practice → Pressure" progression is the core of good level pacing. A well-designed level lets players feel smart — they discover solutions themselves rather than being told what to do. Failure should teach, not punish.'], bullets: ['Teach: introduce the mechanic safely', 'Practice: reinforce in a low-risk context', 'Challenge: test under pressure', 'One mechanic at a time', 'Let players discover — failure should teach'] },
        { heading: '3. Pacing & Player Testing', paragraphs: ['Pacing is the rhythm of the experience — alternating intensity and relaxation. Intense combat sequences are followed by quiet exploration; difficult puzzles are followed by rewards. Good pacing prevents fatigue and keeps players engaged.', 'Player testing is essential. Watch players (not developers) play your level. Note where they get stuck, lost, or frustrated. Players will find solutions and exploits you never imagined. Iterate based on observations, not assumptions — and test again.'], bullets: ['Pacing: alternate intensity and calm', 'High-intensity sections: combat, puzzles, tension', 'Low-intensity sections: exploration, story, rewards', 'Player testing: watch real players, not developers', 'Iterate: fix issues and test again'] }
      ],
      keyPoints: ['Level design guides players through environmental cues', 'Teach mechanics gradually: safe → practice → pressure', 'Pacing alternates intensity to keep players engaged', 'Player testing reveals what developers cannot see'],
      summary: 'Level design is the art of guiding players through a curated experience. By using environmental cues to guide, teaching mechanics gradually, controlling pacing, and testing with real players, you create levels that are intuitive, engaging, and memorable.'
    }
  ];
  window.COURSE_DETAILS = existing;
})();

